/// A set of dependency registrations, usually generated by Arrow Generator.
///
/// Each app target or package gets its own registry (for example `AnalyticsDependencies`).
/// Register them at startup, passing registries before the ones that depend on them:
///
/// ```swift
/// Container.shared.register(CoreDependencies.self, AnalyticsDependencies.self, AppDependencies.self)
/// ```
public protocol DependencyRegistry {
  /// Registers every dependency this registry provides.
  static func register(in container: Container)
}

extension Container {
  /// Registers each registry in order.
  ///
  /// - Important: Eager singletons are created during registration, so pass registries
  ///   before the ones that depend on them.
  public func register(_ registries: any DependencyRegistry.Type...) {
    for registry in registries {
      registry.register(in: self)
    }
  }
}
